`include "disciplines.vams"
module dut(u,e,y,mark,count); input u; output e,y,mark,count; electrical u,e,y,mark,count; real a,b,q,m; integer n;
 analog begin @(initial_step) begin a=0; b=0; q=0.1; m=0; n=0; end
 @(timer(0.125,0.125,1e-12)) begin a=0.3*V(u)*V(u); b=a;
   if(b-a<0) q=2; else q=a; n=n+1; end
 @(timer(0.1875,0.125,1e-12)) begin if(b-a<0) m=2; else m=1; end
 V(e)<+transition(q,0,0.03125,0.03125); V(y)<+0.5*V(y)+V(e);
 V(mark)<+m; V(count)<+n; end endmodule

`include "disciplines.vams"
module dut(u,e,y,mark,count); input u; inout e; output y,mark,count; electrical u,e,y,mark,count;
real s; integer q; analog begin
 @(initial_step) begin s=0; q=0; end
 @(timer(0.25,0,1e-12)) s=1;
 @(cross(V(e)-0.3,+1,1e-12,1e-12)) q=q+1;
 V(e)<+transition(s,0,0.25,0.25);
 V(y)<+q+transition((V(e)>0.3)?2:0,0,0.125,0.125);
 V(mark)<+q; V(count)<+s;
end endmodule

`include "disciplines.vams"
module dut(u,e,y,mark,count); input u; inout e,mark; output y,count; electrical u,e,y,mark,count; real s,t; integer a,b; analog begin
 @(initial_step) begin s=0; t=0; a=0; b=0; end
 @(timer(1,0,1e-12)) s=1;
 @(timer(1.0000000000000002,0,1e-12)) t=1;
 @(cross(V(e)-0.3,+1,1e-12,1e-12)) a=1;
 @(cross(V(mark)-0.3,+1,1e-12,1e-12)) b=1;
 V(e)<+transition(s,0,0.25,0.25); V(mark)<+transition(t,0,0.25,0.25);
 V(y)<+a+2*b; V(count)<+b; end endmodule
